(function ($) {
    "use strict";
    const extra = {
        nepaliClock: function () {
            const currentTime = new Date();
            let hours = currentTime.getHours();
            let minutes = currentTime.getMinutes();
            let seconds = currentTime.getSeconds();
            let ampm = "विहानको";
            if (hours > 12) {
                hours = hours - 12;
                ampm = "अपराह्नको";
            } else if (hours === 0) {
                hours = 12;
            }
            if (minutes < 10) {
                minutes = "0" + minutes;
            }
            if (seconds < 10) {
                seconds = "0" + seconds;
            }
            $("#clock-container").html(ampm + " " +
                NepaliFunctions.ConvertToUnicode(hours) + ":" +
                NepaliFunctions.ConvertToUnicode(minutes) + ":" +
                NepaliFunctions.ConvertToUnicode(seconds));
        },
        chatScroll: function (){
            if ($('.grievanceChat') == !undefined){
                const ChatDiv = $('.grievanceChat');
                const height = ChatDiv[0].scrollHeight;
                ChatDiv.scrollTop(height);
            }
        }

    }
    setInterval(extra.nepaliClock, 1000);
})(jQuery);
